// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime1, uint256 unlockTime2, uint256 amount1, uint256 amount2, uint8 actorSalt) public {
        // Keep amounts reasonable and times in a sensible range
        vm.assume(amount1 <= 1000000 ether);
        vm.assume(amount2 <= 1000000 ether);
        vm.assume(unlockTime1 <= type(uint64).max && unlockTime2 <= type(uint64).max);
        // Ensure two different unlock times to make the difference observable
        vm.assume(unlockTime1 != unlockTime2);

        // Derive a deterministic actor address from the salt (the fuzzer supplies the salt)
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(actorSalt)))));
        vm.assume(actor != address(0) && actor != address(this));

        // Fund actor for the two payable Put calls
        vm.deal(actor, amount1 + amount2 + 100 ether);

        // First Put
        vm.prank(actor);
        c.Put{value: amount1}(unlockTime1);

        // Second Put with a different unlockTime
        vm.prank(actor);
        c.Put{value: amount2}(unlockTime2);

        // The unlockTime for the actor MUST equal the latest supplied argument (unlockTime2)
        // Acc is a public getter returning (uint unlockTime, uint balance)
        (uint storedUnlockTime,) = c.Acc(actor);
        assertTrue(storedUnlockTime == unlockTime2);
    }
}

