// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 firstUnlockTime, uint256 secondUnlockTime, uint256 collectAmount) public {
        address user = address(0x123);
        // Bound times to reasonable future values, with secondUnlockTime strictly less than firstUnlockTime
        uint256 baseTimestamp = block.timestamp + 1 days;
        firstUnlockTime = bound(firstUnlockTime, baseTimestamp, baseTimestamp + 365 days);
        secondUnlockTime = bound(secondUnlockTime, baseTimestamp, firstUnlockTime - 1);
        // Bound collectAmount to be within the deposited balance and above MinSum
        collectAmount = bound(collectAmount, 1 ether, 2 ether);

        // Ensure user has enough ether to deposit
        vm.deal(user, 4 ether);

        // First Put: set a future unlockTime
        vm.prank(user);
        c.Put{value: 2 ether}(firstUnlockTime);

        // Second Put: set an earlier future unlockTime
        vm.prank(user);
        c.Put{value: 0}(secondUnlockTime);

        // Warp to after the second (earlier) unlockTime but before the first
        vm.warp(secondUnlockTime + 1);

        // Try to Collect – should succeed on original, fail on mutant
        vm.prank(user);
        try c.Collect(collectAmount) {
            assertTrue(true);
        } catch {
            assertTrue(false);
        }
    }
}

