pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Attacker {
    C target;
    uint256 selfAmt;
    constructor(C _target) { target = _target; }
    receive() external payable {
        (bool ok, ) = address(target).call{value: selfAmt}("");
        require(ok);
    }
    function attack(uint256 amt) external payable {
        selfAmt = amt;
        target.Put{value: amt}(0);
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint240 amt) public {
        uint256 amount = uint256(amt);
        vm.assume(amount > 0);

        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amount);

        // track ether received by c before the attack
        uint256 balanceBefore = address(c).balance;

        attacker.attack{value: amount}(amount);

        // Check invariant: c's tracked Acc balance for the attacker never exceeds the net ether increase of c
        uint256 balanceAfter = address(c).balance;
        uint256 netEtherReceived = balanceAfter - balanceBefore;
        ( , uint256 accBal) = c.Acc(address(attacker));
        assertTrue(accBal <= netEtherReceived);
    }
}

