pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 am, uint256 unlockTime, uint64 reentryTime) public {
        vm.assume(am > 0 && am < type(uint240).max);
        vm.assume(reentryTime > block.timestamp + 1);

        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), am + 1 ether);

        vm.prank(address(attacker));
        c.Put{value: am}(unlockTime);

        // Advance time to make unlockTime pass, but keep reentryTime later for the attack
        vm.warp(block.timestamp + 1 days);

        uint256 balanceBefore = c.Acc(address(attacker)).balance;
        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(address(attacker));
        attacker.attack(am);

        uint256 balanceAfter = c.Acc(address(attacker)).balance;
        uint256 contractBalanceAfter = address(c).balance;

        assertTrue(balanceAfter <= balanceBefore - am + am);
    }
}

contract ReentrantAttacker {
    C c;
    uint256 targetAm;
    uint256 attackPhase;

    constructor(C _c) {
        c = _c;
    }

    function attack(uint256 am) external payable {
        targetAm = am;
        attackPhase = 0;
        c.Collect(am);
    }

    receive() external payable {
        if (attackPhase == 0) {
            attackPhase = 1;
            c.Put{value: 1 ether}(0);
        }
    }
}

