pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        attacker = new Attacker();
        c = new C(address(this));
    }

    function testFuzz_property(uint256 depositAmount, uint256 reenterAmount) public {
        // Bound amounts to admissible ETH ranges
        depositAmount = bound(depositAmount, 1, 100 ether);
        reenterAmount = bound(reenterAmount, 1, depositAmount);

        // Fund attacker with depositAmount
        vm.deal(address(attacker), depositAmount);

        // Attacker deposits `depositAmount` via Put, triggering a reentrant Put of `reenterAmount` inside receive()
        attacker.attack(address(c), depositAmount, reenterAmount);

        // After the call, the attacker's recorded balance in C should equal exactly the total Ether sent
        uint256 recorded = c.Acc(address(attacker)).balance;
        uint256 totalSent = depositAmount + reenterAmount;
        assertTrue(recorded == totalSent, "balance != total sent");
    }
}

contract Attacker {
    C public target;
    uint256 public reenterAmt;

    function attack(address _target, uint256 depositAmt, uint256 _reenterAmt) external payable {
        target = C(_target);
        reenterAmt = _reenterAmt;
        target.Put{value: depositAmt}(block.timestamp);
    }

    receive() external payable {
        // Reentrant Put with stored amount
        if (address(target) != address(0) && reenterAmt > 0) {
            uint256 amt = reenterAmt;
            reenterAmt = 0; // Prevent infinite recursion
            target.Put{value: amt}(block.timestamp);
        }
    }
}

