        require(collectAmt > 0 && deposit >= collectAmt);
        require(unlockTime > 0);
        c.Put{value: deposit}(unlockTime);
        (, uint balBefore) = c.Acc(address(this));
        bool ok = c.Collect{value: 0}(collectAmt);
        (, uint balAfter) = c.Acc(address(this));
