    constructor(C _c) { c = _c; }
    function run(uint amount, address caller) public payable {
        require(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        uint accBalBefore = c.Acc(caller).balance;
        c.Put{value: amount}(0);
        uint accBalAfterPut = c.Acc(caller).balance;
        uint balAfterPut = address(c).balance;
        bool reverted; try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        uint balAfterCollect = address(c).balance;
