pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depositAmount, uint256 unlockTime, uint256 withdrawAmount) public {
        // keep deposit in admissible range, ensure it is >= 1 ether (MinSum)
        vm.assume(depositAmount >= 1 ether && depositAmount < type(uint256).max / 2);
        vm.assume(withdrawAmount <= depositAmount && withdrawAmount > 0);
        vm.assume(unlockTime > block.timestamp && unlockTime < type(uint256).max / 2);

        address caller = makeAddr("caller");
        vm.deal(caller, depositAmount);

        // deposit to set up balance and unlock time
        vm.prank(caller);
        c.Put{value: depositAmount}(unlockTime);

        uint256 balanceBefore = c.Acc(caller).balance;

        // warp past unlock time
        vm.warp(unlockTime + 1);

        // collect
        vm.prank(caller);
        c.Collect(withdrawAmount);

        uint256 balanceAfter = c.Acc(caller).balance;
        uint256 expectedBalance = balanceBefore - withdrawAmount;

        // Universal rule: after a successful Collect, the caller's balance is reduced by exactly withdrawAmount.
        // The bug subtracts withdrawAmount+1, so balanceAfter will be less than expected when the call succeeds.
        assertTrue(balanceAfter == expectedBalance);
    }
}

