pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockDelay, uint256 preFund) public {
        // admissible: amount must cover MinSum, preFund can be large, unlockDelay non-zero
        vm.assume(amount >= c.MinSum());
        vm.assume(unlockDelay > 0 && unlockDelay <= 365 days);
        vm.assume(preFund >= amount && preFund <= type(uint128).max);

        // adversarial counterparty that receives ETH and returns true, otherwise vm.prank call to EOA always succeeds
        address caller = address(new CallReturnTrue());
        vm.deal(caller, preFund);

        // first Put to establish a balance and an unlock time in the past
        vm.prank(caller);
        c.Put{value: preFund}(1);

        // warp past the unlock time so Collect is allowed
        vm.warp(block.timestamp + unlockDelay + 1);

        uint256 balanceBefore = c.Acc(caller).balance;

        // Collect the amount; caller receives ETH via call
        vm.prank(caller);
        c.Collect(amount);

        uint256 balanceAfter = c.Acc(caller).balance;

        // General rule: the balance decrement must equal the withdrawn amount
        assertTrue(balanceBefore - balanceAfter == amount);
    }
}

contract CallReturnTrue {
    // Receives ETH and returns true, enabling the if (_s) branch in Collect
    fallback() external payable { }
}

