pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(uint256 initialDeposit, uint256 withdrawAmount, uint64 unlockTime) public {
        // Bound to keep amounts within admissable range (min deposit = MinSum = 1 ether, withdraw between 1 and deposit)
        uint256 minDeposit = c.MinSum();
        initialDeposit = bound(initialDeposit, minDeposit, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, initialDeposit);
        unlockTime = uint64(bound(uint256(unlockTime), 0, type(uint64).max - 1));

        address caller = address(this);

        // Record initial ETH balance of caller
        uint256 callerEthBefore = address(caller).balance;

        // Give caller ETH and deposit into C
        vm.deal(caller, initialDeposit);
        vm.prank(caller);
        c.Put{value: initialDeposit}(unlockTime);

        // Ensure unlockTime has passed
        vm.warp(block.timestamp + unlockTime + 1);

        // Query pre-collect Acc balance
        (uint256 /*unlockTimeAcc*/, uint256 balanceBefore) = c.Acc(caller);

        // Perform Collect
        vm.prank(caller);
        c.Collect(withdrawAmount);

        // Query post-collect Acc balance and ETH balance
        (uint256 /*unlockTimeAcc2*/, uint256 balanceAfter) = c.Acc(caller);
        uint256 callerEthAfter = address(caller).balance;

        // The caller received exactly withdrawAmount ETH (call succeeded)
        // So Acc balance should have decreased by withdrawAmount
        // The invariant: balanceBefore - balanceAfter == withdrawAmount
        // The bug subtracts withdrawAmount + 1, making balanceBefore - balanceAfter > withdrawAmount
        // Equivalently, (balanceBefore - balanceAfter) must equal the withdrawn amount
        assertTrue(balanceBefore - balanceAfter == withdrawAmount);
    }
}

