        uint256 totalSent = amount;

        // Attacker initiates reentrant Put via fallback/receive
        vm.prank(address(attacker));
        attacker.attack{value: amount}(unlockTime);

        // Compute total balance held by contract
        uint256 totalContractBalance = address(c).balance;

        // Sum all Acc balances (only attacker has non-zero if attack succeeded)
        ( , uint256 attackerBalance) = c.Acc(address(attacker));

