contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // Bound to admissible domain: positive deposit up to 1000 ether, collect up to deposit
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        // Deploy reentrant attacker helper
        ReentrantAttacker attacker = new ReentrantAttacker();
        address attackerAddr = address(attacker);

        // Fund attacker and target contract
        vm.deal(attackerAddr, depositAmount);
        vm.deal(address(c), 0);

        // Set attacker's target contract
        attacker.setTarget(address(c));

        // Record initial sum of all Acc balances
        uint256 sumBefore = c.Acc(address(this)).balance + c.Acc(attackerAddr).balance;

        // Attacker deposits via Put, triggering reentrant Put in fallback
        vm.prank(attackerAddr);
        attacker.attack{value: depositAmount}();

        // Warp past unlock time and collect
        vm.warp(block.timestamp + 1 days);
        vm.prank(attackerAddr);
        c.Collect(collectAmount);

        // Record final sum of all Acc balances
        uint256 sumAfter = c.Acc(address(this)).balance + c.Acc(attackerAddr).balance;

        // Rule: sum of recorded balances must not exceed initial sum + deposited Ether - collected Ether
        uint256 netDeposits = depositAmount - collectAmount;
        assertTrue(sumAfter - sumBefore <= netDeposits);
    }
}

