pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 balanceBefore, uint256 unlockTime, uint256 amount, bool warpPast) public {
        // Admissible domains: balanceBefore and amount are uint256; but to be meaningful and avoid overflow,
        // we bound them to [0, 1e30]. UnlockTime can be any uint256; warpPast tells us whether to warp past unlockTime.
        balanceBefore = bound(balanceBefore, 0, 1e30);
        amount = bound(amount, 0, 1e30);
        // Ensure amount <= balanceBefore so the subtraction won't underflow (the real Collect also requires that)
        vm.assume(amount <= balanceBefore);

        // Use a deterministic address for the caller (not the test contract)
        address caller = address(0x1234);
        vm.deal(caller, 1000 ether);

        // Setup: give the caller some balance and unlock time in the contract
        vm.prank(caller);
        // We can't directly set Acc[caller].balance, so we call Put with some ether to establish the balance
        c.Put{value: balanceBefore}(unlockTime);

        // Warp if needed
        if (warpPast) {
            vm.warp(block.timestamp + 1000);
            // Ensure warp actually puts us past unlockTime
            vm.assume(block.timestamp > unlockTime);
        }

        // Now attempt Collect
        vm.prank(caller);
        bool ok;
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: if Collect succeeded (ok == true), then the balance before call must have been at least MinSum (1 ether).
        // We can check this by reading the contract's MinSum and comparing to balanceBefore.
        // The original contract respects this; the mutant does not when balanceBefore < MinSum but >= amount and unlocked.
        if (ok) {
            assertTrue(balanceBefore >= c.MinSum());
        } else {
            // If it failed, no constraint on balanceBefore versus MinSum (the invariant doesn't require anything).
            // We just need a non-trivial assertion that passes for reference and fails for mutant.
            // Since the invariant is conditional on success, an unconditional assertion like "balanceBefore < MinSum => revert"
            // would be too strong for reference (it might succeed for some inputs that happen to revert for other reasons).
            // The pattern above is correct: on success, balanceBefore >= MinSum.
            // For the reference, this holds always. For the mutant, there exists some input (balanceBefore < MinSum, unlocked, amount <= balanceBefore)
            // where Collect succeeds, violating the assertion.
            // However, we must ensure the test does give a true assertTrue for the reference in the else branch.
            // To avoid a vacuous pass when ok==false and balanceBefore is small, we just use a no-op: assertTrue(true).
            assertTrue(true);
        }
    }
}

